// TestSeriesNameChains pins the SERIES chain's tier ORDER (display-naming
// 2.1) — each tier against the fact of every tier below it, over one
// document carrying all four legs at once: override > config-driven walk >
// serial-parser title > parsed.dir_name_raw > last path segment. The
// detailed per-leg floors (empty/mistyped walk entries, raw-style legs,
// Cyrillic verbatim) are TestSeriesDisplayName's table; this is the
// chain-order joint.
func TestSeriesNameChains(t *testing.T) {
	src := func(ids ...string) []TitleSourceBinding {
		bindings := make([]TitleSourceBinding, len(ids))
		for i, id := range ids {
			bindings[i] = TitleSourceBinding{ID: id, Enabled: true}
		}
		return bindings
	}
	n := Namer{
		GroupStyle:   "clean",
		TitleSources: src("shikimori"),
		LangPrefs:    []string{"ru"},
	}
	// Every tier's fact, strongest first: override (passed per call), the
	// walk's shikimori title, the parser title, the raw directory name, and
	// the path's last segment.
	const doc = `{"sources":{"shikimori":{"title":"Ария (walk)"},"serial-parser":{"title":"Ария (parser)"},"zzz":{"title":"не источник"}},"parsed":{"dir_name_raw":"Ария (raw)"}}`
	sr := store.Series{RelativePath: "Медиа/Ария (segment)", Document: json.RawMessage(doc)}

	t.Run("override_beats_the_walk", func(t *testing.T) {
		if got := n.SeriesName(sr, "Моё название"); got != "Моё название" {
			t.Fatalf("override tier lost: got %q", got)
		}
	})
	t.Run("walk_beats_parser_title", func(t *testing.T) {
		if got := n.SeriesName(sr, ""); got != "Ария (walk)" {
			t.Fatalf("walk tier lost: got %q", got)
		}
	})
	t.Run("parser_title_beats_dir_name_raw", func(t *testing.T) {
		noWalk := n
		noWalk.TitleSources = nil
		if got := noWalk.SeriesName(sr, ""); got != "Ария (parser)" {
			t.Fatalf("parser tier lost: got %q", got)
		}
	})
	t.Run("dir_name_raw_beats_last_segment", func(t *testing.T) {
		noWalk := n
		noWalk.TitleSources = nil
		noParser := store.Series{RelativePath: sr.RelativePath, Document: json.RawMessage(`{"parsed":{"dir_name_raw":"Ария (raw)"}}`)}
		if got := noWalk.SeriesName(noParser, ""); got != "Ария (raw)" {
			t.Fatalf("raw-name tier lost: got %q", got)
		}
		if got := noWalk.SeriesName(store.Series{RelativePath: "Медиа/Ария (segment)", Document: json.RawMessage(`{}`)}, ""); got != "Ария (segment)" {
			t.Fatalf("last-segment floor lost: got %q", got)
		}
	})
	t.Run("raw_style_truncates_to_override_raw_segment", func(t *testing.T) {
		raw := n
		raw.GroupStyle = "raw"
		if got := raw.SeriesName(sr, ""); got != "Ария (raw)" {
			t.Fatalf("raw style must skip walk + parser title: got %q", got)
		}
		if got := raw.SeriesName(store.Series{RelativePath: "Медиа/Ария (segment)", Document: json.RawMessage(`{}`)}, ""); got != "Ария (segment)" {
			t.Fatalf("raw style floor lost: got %q", got)
		}
	})
}

// TestItemNameChains pins the ITEM chain's tier ORDER (display-naming D-2) —
// override > composed element name (facts joined to the resolved series,
// rendered through the active template) > the config-driven walk over the
// item's OWN namespaces > _view.title.value verbatim > "". The detailed
// floor shapes (unresolved/tombstoned series, mistyped walk entries, number
// passthrough, empty walk inputs) are TestItemDisplayNamePrecedence's table;
// this is the chain-order joint.
func TestItemNameChains(t *testing.T) {
	src := func(ids ...string) []TitleSourceBinding {
		bindings := make([]TitleSourceBinding, len(ids))
		for i, id := range ids {
			bindings[i] = TitleSourceBinding{ID: id, Enabled: true}
		}
		return bindings
	}
	n := Namer{
		GroupStyle:   "clean",
		ElementTmpl:  "{title} · S{season}E{episode}",
		TitleSources: src("shikimori"),
		LangPrefs:    []string{"ru"},
		SeriesByPath: map[string]store.Series{
			"Атланта (2016)": {
				RelativePath: "Атланта (2016)",
				Status:       "ready",
				Document:     json.RawMessage(`{"sources":{"serial-parser":{"title":"Атланта"}}}`),
			},
		},
	}
	item := func(doc string) store.Item {
		return store.Item{RelativePath: "Атланта (2016)/E01.mkv", Document: json.RawMessage(doc)}
	}
	// Every tier's fact at once: the join facts (composed), the item's OWN
	// walk title, and the _view floor.
	const doc = `{"parsed":{"series_relative_path":"Атланта (2016)"},"sources":{"serial-parser":{"season":2,"episode":6},"shikimori":{"title":"Атланта (walk)"}},"_view":{"title":{"value":"Файловое имя"}}}`

	t.Run("override_beats_composed", func(t *testing.T) {
		if got := n.ItemName(item(doc), "Моё название"); got != "Моё название" {
			t.Fatalf("override tier lost: got %q", got)
		}
	})
	t.Run("composed_beats_the_walk", func(t *testing.T) {
		if got := n.ItemName(item(doc), ""); got != "Атланта · S02E06" {
			t.Fatalf("composed tier lost: got %q", got)
		}
	})
	t.Run("walk_beats_view_floor", func(t *testing.T) {
		noTmpl := n
		noTmpl.ElementTmpl = "" // the composed leg vanishes; the walk holds
		if got := noTmpl.ItemName(item(doc), ""); got != "Атланта (walk)" {
			t.Fatalf("walk tier lost: got %q", got)
		}
	})
	t.Run("view_floor_holds_when_the_walk_floors", func(t *testing.T) {
		noTmpl := n
		// Both legs above _view must be gone: the template (the composed
		// tier) and the walk inputs (the walk tier) — the _view floor holds.
		noTmpl.ElementTmpl = ""
		noTmpl.TitleSources = nil
		if got := noTmpl.ItemName(item(doc), ""); got != "Файловое имя" {
			t.Fatalf("_view floor lost: got %q", got)
		}
	})
	t.Run("empty_floor_when_nothing_resolves", func(t *testing.T) {
		if got := n.ItemName(item(`{"ffprobe":{}}`), ""); got != "" {
			t.Fatalf("the chain must floor to \"\": got %q", got)
		}
	})
	t.Run("failed_join_floors_to_the_walk", func(t *testing.T) {
		// An unresolved series anchor kills the composed leg only — the walk
		// still answers (never the composed name of a fabricated series).
		bad := `{"parsed":{"series_relative_path":"Нет такого сериала"},"sources":{"serial-parser":{"season":1,"episode":2},"shikimori":{"title":"Атланта (walk)"}}}`
		if got := n.ItemName(item(bad), ""); got != "Атланта (walk)" {
			t.Fatalf("failed join must floor to the walk: got %q", got)
		}
	})
}

