// TestPickLanguage covers the language-pick policy (plugin-title-enrichment)
// directly — the ONE named home of pref→key mapping: "ru" reads `russian`,
// "en" reads `romaji`, prefs apply in order (first usable pick wins), an
// unknown pref code floors to the next pref, an empty key value is skipped,
// and no usable pick floors to "".
func TestPickLanguage(t *testing.T) {
	ns := map[string]any{
		"romaji":  "Атланта romaji",
		"russian": "Атланта",
	}
	cases := []struct {
		name  string
		ns    map[string]any
		prefs []string
		want  string
	}{
		{name: "ru_first_pref_reads_russian", ns: ns, prefs: []string{"ru", "en"}, want: "Атланта"},
		{name: "en_pref_reads_romaji", ns: ns, prefs: []string{"en"}, want: "Атланта romaji"},
		{name: "order_matters", ns: ns, prefs: []string{"en", "ru"}, want: "Атланта romaji"},
		{name: "unknown_pref_floors_to_next", ns: ns, prefs: []string{"jp", "ru"}, want: "Атланта"},
		{name: "empty_value_skipped_to_next_pref", ns: map[string]any{"russian": "", "romaji": "Атланта romaji"}, prefs: []string{"ru", "en"}, want: "Атланта romaji"},
		{name: "mistyped_value_skipped", ns: map[string]any{"russian": 7}, prefs: []string{"ru"}, want: ""},
		{name: "empty_prefs_floor", ns: ns, prefs: nil, want: ""},
		{name: "all_misses_floor", ns: map[string]any{"romaji": "X"}, prefs: []string{"ru"}, want: ""},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			if got := pickLanguage(tc.ns, tc.prefs); got != tc.want {
				t.Fatalf("pickLanguage(%v, %v) = %q, want %q", tc.ns, tc.prefs, got, tc.want)
			}
		})
	}
}

// TestItemNameTemplate covers the pure element-template composer
// (display-naming 2.2): tokens exactly {title}/{season}/{episode} plus free
// text; composer-fixed two-digit zero-padding (JS padStart(2,"0") — a 3+
// digit episode renders in full); an absent token renders as the EMPTY
// STRING — never a placeholder, never the raw token.
func TestItemNameTemplate(t *testing.T) {
	i64 := func(v int64) *int64 { return &v }
	cases := []struct {
		name string
		tmpl string
		tok  elementTokens
		want string
	}{
		{
			name: "two_digit_padding_default_shape",
			tmpl: "{title} · S{season}E{episode}",
			tok:  elementTokens{Title: "Секретные материалы", Season: i64(2), Episode: i64(6)},
			want: "Секретные материалы · S02E06",
		},
		{
			name: "three_digit_episode_in_full",
			tmpl: "{title} · S{season}E{episode}",
			tok:  elementTokens{Title: "Show", Season: i64(2), Episode: i64(146)},
			want: "Show · S02E146",
		},
		{
			name: "absent_title_renders_empty",
			tmpl: "S{season}E{episode} — {title}",
			tok:  elementTokens{Season: i64(2), Episode: i64(6)},
			want: "S02E06 — ",
		},
		{
			name: "absent_season_renders_empty",
			tmpl: "{season}x{episode}",
			tok:  elementTokens{Episode: i64(6)},
			want: "x06",
		},
		{
			name: "absent_episode_renders_empty",
			tmpl: "{season}x{episode}",
			tok:  elementTokens{Season: i64(1)},
			want: "01x",
		},
		{
			name: "free_text_and_cyrillic_verbatim_unknown_group_is_literal",
			tmpl: "Эпизод {episode} из {total} — {title}",
			tok:  elementTokens{Title: "Ход королевской кобры", Episode: i64(3)},
			want: "Эпизод 03 из {total} — Ход королевской кобры",
		},
		{
			name: "injected_title_is_never_rescanned",
			tmpl: "{title}/{episode}",
			tok:  elementTokens{Title: "{episode}", Episode: i64(6)},
			want: "{episode}/06",
		},
		{
			name: "empty_template_renders_empty",
			tmpl: "",
			tok:  elementTokens{Title: "Show", Season: i64(1), Episode: i64(1)},
			want: "",
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			if got := composeItemName(tc.tmpl, tc.tok); got != tc.want {
				t.Fatalf("composeItemName(%q) = %q, want %q", tc.tmpl, got, tc.want)
			}
		})
	}
}

// TestItemDisplayNamePrecedence covers ItemName's exact precedence chain
// (display-naming 2.3): title_override > composed element name (episode facts
// + resolved series + template) > the config-driven title walk over the
// item's OWN namespaces (plugin-title-enrichment — the floor for EVERY
// failed composition, films included) > _view.title.value verbatim > "".
// Includes the floor legs — film/tv/image paths (no facts -> no template ->
// walk -> _view floor -> ""), unresolved-series and deleted-series floors
// (never fabricated), the walk cases (object RU pick, string verbatim,
// mistyped floors to _view, walk beats _view, number passthrough after a
// failed walk, empty walk inputs byte-identical) — and the fixed-order
// namespace iteration (serial-parser, then tv-parser, then sorted rest; Go
// map order never leaks).
func TestItemDisplayNamePrecedence(t *testing.T) {
	// One namer, one resolved series ("Атланта (2016)" -> parser title
	// "Атланта", plus one tombstoned row), the module-default template, and
	// the module's title-walk inputs — every pre-walk case below must stay
	// green WITH the walk inputs live, and every walk case must sit exactly
	// between the composed name and the _view floor.
	src := func(ids ...string) []TitleSourceBinding {
		bindings := make([]TitleSourceBinding, len(ids))
		for i, id := range ids {
			bindings[i] = TitleSourceBinding{ID: id, Enabled: true}
		}
		return bindings
	}
	n := Namer{
		GroupStyle:   "clean",
		ElementTmpl:  "{title} · S{season}E{episode}",
		TitleSources: src("shikimori", "kinopoisk"),
		LangPrefs:    []string{"ru", "en"},
		SeriesByPath: map[string]store.Series{
			"Атланта (2016)": {
				RelativePath: "Атланта (2016)",
				Status:       "ready",
				Document:     json.RawMessage(`{"sources":{"serial-parser":{"title":"Атланта"}}}`),
			},
			"Удалённый сериал": {
				RelativePath: "Удалённый сериал",
				Status:       "deleted",
				Document:     json.RawMessage(`{"sources":{"serial-parser":{"title":"Призрак"}}}`),
			},
		},
	}
	item := func(doc string) store.Item {
		return store.Item{RelativePath: "Атланта (2016)/E01.mkv", Document: json.RawMessage(doc)}
	}
	cases := []struct {
		name     string
		doc      string
		override string
		want     string
	}{
		{
			name:     "override_beats_composed",
			doc:      `{"parsed":{"series_relative_path":"Атланта (2016)"},"sources":{"serial-parser":{"season":2,"episode":6}},"_view":{"title":{"value":"Файловое имя"}}}`,
			override: "Моё название",
			want:     "Моё название",
		},
		{
			name: "composed_beats_view_floor",
			doc:  `{"parsed":{"series_relative_path":"Атланта (2016)"},"sources":{"serial-parser":{"season":2,"episode":6}},"_view":{"title":{"value":"Файловое имя"}}}`,
			want: "Атланта · S02E06",
		},
		{
			name: "view_floor_when_no_facts",
			doc:  `{"_view":{"title":{"value":"Обложка альбома"}}}`,
			want: "Обложка альбома",
		},
		{
			name: "empty_when_nothing_resolves",
			doc:  `{"ffprobe":{}}`,
			want: "",
		},
		{
			name: "unresolved_series_floors_to_view",
			doc:  `{"parsed":{"series_relative_path":"Нет такого сериала"},"sources":{"tv-parser":{"season":1,"episode":2}},"_view":{"title":{"value":"Эпизод без сериала"}}}`,
			want: "Эпизод без сериала",
		},
		{
			name: "deleted_series_never_joined",
			doc:  `{"parsed":{"series_relative_path":"Удалённый сериал"},"sources":{"tv-parser":{"season":1,"episode":2}},"_view":{"title":{"value":"Эпизод призрака"}}}`,
			want: "Эпизод призрака",
		},
		{
			name: "view_number_value_passes_verbatim",
			doc:  `{"_view":{"title":{"value":42}}}`,
			want: "42",
		},
		// ---- the walk floor over the item's OWN namespaces (plugin-title-
		// enrichment): every failed-composition shape, films included ----
		{
			name: "film_walk_object_title_ru_pick",
			doc:  `{"sources":{"shikimori":{"title":{"romaji":"Укигуме romaji","russian":"Укигуме"}}},"_view":{"title":{"value":"Файл фильма"}}}`,
			want: "Укигуме",
		},
		{
			name: "film_walk_string_title_verbatim",
			doc:  `{"sources":{"kinopoisk":{"title":"Укигуме (2019)"}},"_view":{"title":{"value":"Файл фильма"}}}`,
			want: "Укигуме (2019)",
		},
		{
			name: "walk_priority_order_first_non_empty_wins",
			doc:  `{"sources":{"shikimori":{"title":""},"kinopoisk":{"title":"Укигуме"}}}`,
			want: "Укигуме",
		},
		{
			name: "walk_beats_view_title_string",
			doc:  `{"sources":{"shikimori":{"title":"アトランタ"}},"_view":{"title":{"value":"Файловое имя"}}}`,
			want: "アトランタ",
		},
		{
			name: "walk_mistyped_title_floors_to_view",
			doc:  `{"sources":{"shikimori":{"title":42}},"_view":{"title":{"value":"Файловое имя"}}}`,
			want: "Файловое имя",
		},
		{
			name: "walk_language_miss_floors_to_view",
			doc:  `{"sources":{"shikimori":{"title":{"russian":"","romaji":""}}},"_view":{"title":{"value":"Файл фильма"}}}`,
			want: "Файл фильма",
		},
		{
			name: "view_number_passes_after_failed_walk",
			doc:  `{"sources":{"shikimori":{"title":true}},"_view":{"title":{"value":42}}}`,
			want: "42",
		},
		{
			name: "composed_still_beats_the_walk",
			doc:  `{"parsed":{"series_relative_path":"Атланта (2016)"},"sources":{"serial-parser":{"season":2,"episode":6},"shikimori":{"title":"アトランタ"}}}`,
			want: "Атланта · S02E06",
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			if got := n.ItemName(item(tc.doc), tc.override); got != tc.want {
				t.Fatalf("ItemName = %q, want %q", got, tc.want)
			}
		})
	}
	t.Run("no_template_no_composition", func(t *testing.T) {
		noTmpl := n
		noTmpl.ElementTmpl = ""
		doc := `{"parsed":{"series_relative_path":"Атланта (2016)"},"sources":{"serial-parser":{"season":2,"episode":6}}}`
		if got := noTmpl.ItemName(item(doc), ""); got != "" {
			t.Fatalf("ItemName without template = %q, want the empty floor", got)
		}
	})
	t.Run("empty_walk_inputs_byte_identical", func(t *testing.T) {
		noWalk := Namer{
			GroupStyle:  "clean",
			ElementTmpl: "{title} · S{season}E{episode}",
			SeriesByPath: map[string]store.Series{
				"Атланта (2016)": {
					RelativePath: "Атланта (2016)",
					Status:       "ready",
					Document:     json.RawMessage(`{"sources":{"serial-parser":{"title":"Атланта"}}}`),
				},
			},
		}
		// The zero-walk namer (plain unit-test namers) must skip the leg
		// entirely: the shikimori namespace is NOT read, the chain floors
		// straight to _view.title — byte-identical to the pre-walk chain.
		doc := `{"sources":{"shikimori":{"title":"アトランタ"}},"_view":{"title":{"value":"Файловое имя"}}}`
		if got := noWalk.ItemName(item(doc), ""); got != "Файловое имя" {
			t.Fatalf("ItemName without walk inputs = %q, want the _view floor %q", got, "Файловое имя")
		}
		if got := noWalk.ItemName(item(`{"_view":{"title":{"value":42}}}`), ""); got != "42" {
			t.Fatalf("ItemName without walk inputs (number) = %q, want %q", got, "42")
		}
	})
}

// TestEpisodeFactsOrder covers the fixed namespace read order (display-naming
// 2.3, D-3): serial-parser first, then tv-parser, then the remaining
// namespaces sorted; a namespace carrying only ONE of the two facts never
// qualifies; the same values every read, never map-order-dependent.
func TestEpisodeFactsOrder(t *testing.T) {
	facts := func(doc string) (path string, season, episode int64, ok bool) {
		return EpisodeFacts(DocMap(json.RawMessage(doc)))
	}
	t.Run("serial_parser_beats_other_namespaces", func(t *testing.T) {
		path, s, e, ok := facts(`{"parsed":{"series_relative_path":"S"},"sources":{"zzz":{"season":9,"episode":9},"serial-parser":{"season":1,"episode":2}}}`)
		if !ok || path != "S" || s != 1 || e != 2 {
			t.Fatalf("got path=%q s=%d e=%d ok=%v, want S/1/2/true", path, s, e, ok)
		}
	})
	t.Run("tv_parser_beats_sorted_rest", func(t *testing.T) {
		_, s, e, ok := facts(`{"parsed":{"series_relative_path":"S"},"sources":{"zzz":{"season":9,"episode":9},"tv-parser":{"season":3,"episode":4}}}`)
		if !ok || s != 3 || e != 4 {
			t.Fatalf("got s=%d e=%d ok=%v, want 3/4/true", s, e, ok)
		}
	})
	t.Run("sorted_rest_when_no_known_namespace", func(t *testing.T) {
		_, s, e, ok := facts(`{"parsed":{"series_relative_path":"S"},"sources":{"бета":{"season":1,"episode":1},"альфа":{"season":5,"episode":7}}}`)
		if !ok || s != 5 || e != 7 {
			t.Fatalf("got s=%d e=%d ok=%v, want 5/7/true (альфа sorts first)", s, e, ok)
		}
	})
	t.Run("half_facts_never_qualify", func(t *testing.T) {
		_, _, _, ok := facts(`{"parsed":{"series_relative_path":"S"},"sources":{"zzz":{"season":9,"episode":9},"serial-parser":{"season":1}}}`)
		if !ok {
			t.Fatalf("half-fact namespace must be skipped in favor of the next")
		}
		_, _, _, ok = facts(`{"parsed":{"series_relative_path":"S"},"sources":{"serial-parser":{"episode":2}}}`)
		if ok {
			t.Fatalf("episode-only namespace must not qualify")
		}
	})
	t.Run("non_integer_facts_never_qualify", func(t *testing.T) {
		_, _, _, ok := facts(`{"parsed":{"series_relative_path":"S"},"sources":{"serial-parser":{"season":"2","episode":6}}}`)
		if ok {
			t.Fatalf("string season must not qualify")
		}
		_, _, _, ok = facts(`{"parsed":{"series_relative_path":"S"},"sources":{"serial-parser":{"season":2.5,"episode":6}}}`)
		if ok {
			t.Fatalf("fractional season must not qualify")
		}
	})
	t.Run("no_anchor_no_facts", func(t *testing.T) {
		_, _, _, ok := facts(`{"sources":{"serial-parser":{"season":1,"episode":2}}}`)
		if ok {
			t.Fatalf("missing series_relative_path must yield no facts")
		}
	})
}
